"""Additive threshold-update UI, independent from study forms and calculations."""
import html
import json
import sys

URL='https://github.com/BiosystemEngineeringLab-IITB/merit-ml'
def entry(disabled=False):
    control=('<button type="button" disabled aria-disabled="true" style="filter:blur(.55px);opacity:.55">Update thresholds</button>' if disabled else '<a href="/thresholds" target="_blank" rel="noopener" style="font-weight:700;border:1px solid currentColor;border-radius:7px;padding:7px 10px">Update thresholds</a>')
    return '<span class="merit-threshold-entry">'+control+('</span><span style="font-size:11px">Available in <a href="'+URL+'" target="_blank" rel="noopener">Docker</a></span>' if disabled else '</span>')
def report_note(text,ref):
    disabled=sys.platform=='emscripten'
    marker='<div id="merit-reference-status" style="padding:9px 18px;font:13px sans-serif;border-bottom:1px solid #a8bdbd">'+entry(disabled)
    marker+=' <strong>Analytical alert reference: '+html.escape(ref['reference_version'])+'</strong>'
    if ref.get('update_provenance'):
        p=ref['update_provenance'];marker+=' · '+html.escape(p['description'])+' · '+str(ref['reference_matrices'])+' matrices. Custom score cut-offs, when entered, take precedence.'
        # Only the display phrase is renamed. FAIR principle R1 attribution remains untouched.
        text=text.replace('reference R1','reference '+html.escape(ref['reference_version'])).replace('reference set R1','reference set '+html.escape(ref['reference_version'])).replace('reference cohort (R1)','reference cohort ('+html.escape(ref['reference_version'])+')')
    marker+='</div>'
    if not disabled:
        marker+='''<script>window.addEventListener('storage',function(e){if(e.key==='merit-reference-changed'){const f=document.getElementById('run-form');if(f)f.requestSubmit();}});</script>'''
    import re
    return re.sub(r'(<body[^>]*>)',lambda m:m[0]+marker,text,count=1)

def page():
    return r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Update thresholds · MERIT-ML</title><style>
:root{color-scheme:light;--bg:#f5f3ec;--paper:white;--ink:#143035;--muted:#50656b;--line:#bacbce;--accent:#086d70}html[data-theme=dark]{color-scheme:dark;--bg:#101b1e;--paper:#18282d;--ink:#e4eff1;--muted:#b5c8cc;--line:#45626b;--accent:#71dad5}body{background:var(--bg);color:var(--ink);font:15px/1.6 system-ui;margin:0}main{max-width:1050px;margin:30px auto;padding:0 20px}section{background:var(--paper);border:1px solid var(--line);padding:20px;margin:18px 0;border-radius:12px}h1{font-size:27px}h2{font-size:19px}p{color:var(--muted)}a{color:var(--accent)}button,input,select{font:inherit;padding:9px;border:1px solid var(--line);border-radius:6px;color:var(--ink);background:var(--paper)}button{cursor:pointer;color:var(--accent);font-weight:650}button:disabled{opacity:.45;cursor:default}label{display:inline-block;margin:8px 18px 8px 0}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border:1px solid var(--line);padding:8px;text-align:left}progress{width:100%;height:22px;accent-color:var(--accent)}.warn{border-left:4px solid #cc8f16;padding:10px}.scroll{overflow-x:auto}.status{white-space:pre-wrap}small{color:var(--muted)}[hidden]{display:none!important}</style></head><body><main>
<a href="/">MERIT-ML</a> · <a href="/manual/#23-update-analytical-alert-thresholds" target="_blank">Instructions</a>
<h1>Update thresholds</h1><p>This optional local operation calculates a new analytical-alert reference from public Workbench studies. It does not alter measurements, metric definitions, classes or sample-count support. Original R1 remains available. Your change takes effect only after you review and approve it.</p>
<section><h2>Reference currently in use</h2><div id="active">Loading…</div><button id="restore">Restore original R1</button></section>
<section><h2>1. Choose public release dates</h2><p>Both dates are included. This uses the repository's <strong>public release date</strong>, not submission or revision date. Studies not confirmed public, future releases and unknown/conflicting dates are excluded.</p>
<label>From <input type="date" id="from" required></label><label>Through <input type="date" id="through" required></label><br>
<label>Reference cohort <select id="mode"><option value="extend_r1">Original R1 plus selected studies</option><option value="selected_range">Selected date range only</option></select></label>
<p>Extending R1 keeps its original 11,749 derived score rows and adds new matrix identities once. Original scores are not silently replaced. The date-range-only option excludes R1's original cohort. All four checks use their default analytical settings and ML-eligible samples.</p><button id="prepare">Find public studies</button></section>
<section><h2>2. Review the cohort and calculate</h2><select id="history" aria-label="Saved reference runs"><option value="">Choose a previous run</option></select><div id="selection"></div><p>Registered analyses and possible endpoints can be counted before download. The number of valid matrices and assessable scores is determined during calculation.</p>
<button id="start" disabled>Calculate thresholds</button> <button id="pause" disabled>Pause after current study</button><progress id="progress" max="100" value="0"></progress><div id="status" role="status" aria-live="polite" class="status"></div>
<p>One study is processed at a time. Raw responses, matrices and large intermediates are removed after compact score/provenance records are saved. Disk use must still accommodate the largest study temporarily. Completed studies are retained so an interrupted run can resume. Large cohorts can take hours or days; there is no fixed completion time.</p></section>
<section id="review" hidden><h2>3. Compare and approve</h2><div id="stats"></div><div class="scroll"><table><thead><tr><th>Check</th><th>R1 extreme (2.5%)</th><th>Candidate extreme</th><th>R1 low (10%)</th><th>Candidate low</th><th>Assessable matrices</th><th>Median (IQR)</th></tr></thead><tbody id="cutoffs"></tbody></table></div>
<p id="coverage" class="warn"></p><label id="ack-label" hidden><input type="checkbox" id="ack"> I understand that this reference has incomplete coverage and may be affected by the omitted studies/checks.</label><br><button id="approve">Approve and activate these thresholds</button><div id="downloads"></div>
<p>Approval stores a dated reference in your local application. Original R1 is never overwritten. The 2.5th, 5th, 7.5th and 10th percentiles are retained, so Show tools continues to work. Explicit custom score cut-offs still take precedence. Open reports refresh when approval is signalled by this page; otherwise use Apply or reopen the report.</p></section>
<p id="error" class="warn" hidden></p></main><script>
try{document.documentElement.dataset.theme=localStorage.getItem('merit-ml-theme')||'light'}catch{}
const q=id=>document.getElementById(id);let current=null,candidate=null,base=null,timer=null;const fmt=x=>Number(x).toLocaleString(undefined,{maximumFractionDigits:3});
const now=new Date();q('through').value=now.toISOString().slice(0,10);now.setUTCMonth(now.getUTCMonth()-6);q('from').value=now.toISOString().slice(0,10);q('from').max=q('through').max=q('through').value;
function error(e){q('error').hidden=false;q('error').textContent=e.message||e}
async function api(path,body){const r=await fetch('/api/thresholds'+path,{cache:'no-store',...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
async function overview(){const d=await api('');base=d.baseline;q('active').textContent=d.active.reference_version+' · '+d.active.reference_cohort;const history=q('history');history.replaceChildren(new Option('Choose a previous run',''));for(const x of d.runs)history.add(new Option(x.id+' · '+x.state,x.id));}
function render(s){q('from').value=s.start_date;q('through').value=s.end_date;q('mode').value=s.mode;q('selection').textContent=(s.selected_studies??'…')+' public studies · '+(s.registered_analyses??'…')+' registered analyses · '+(s.endpoints_to_check??'…')+' possible endpoints to check';q('status').textContent=s.state+' · '+s.message+(s.current_study?'\n'+s.current_study:'')+(s.current_check?' · '+s.current_check.stage+' '+(s.current_check.analysis_id||'')+' '+(s.current_check.endpoint||''):'')+'\n'+(s.completed_studies||0)+' / '+(s.total_studies??s.selected_studies??0)+' studies completed · '+(s.valid_matrices||0)+' valid matrices';q('progress').value=s.state==='review'||s.state==='approved'?100:s.total_studies?100*(s.completed_studies||0)/s.total_studies:0;
q('start').disabled=!['ready','paused','interrupted','failed'].includes(s.state)||!s.selected_studies;q('start').textContent=['paused','interrupted','failed'].includes(s.state)?'Resume calculation':'Calculate thresholds';q('pause').disabled=s.state!=='running';q('review').hidden=!s.candidate;
if(s.candidate){candidate=s.candidate;const r=candidate.reference,p=r.update_provenance;q('stats').textContent=r.reference_studies+' reference studies · '+r.reference_analyses+' reference analyses · '+r.reference_matrices+' reference matrices ('+Object.entries(r.matrices_by_endpoint).map(([k,n])=>k+': '+n).join(', ')+') · '+p.new_valid_matrices+' valid matrices retrieved · '+p.baseline_matrices+' baseline matrices · '+p.duplicate_baseline_matrices_not_added+' baseline duplicates not added. Calculation: '+p.retrieval_started_at+' to '+p.retrieval_finished_at;
q('cutoffs').replaceChildren();for(const [k,name]of Object.entries({missingness:'Missing entries and zeros',low_information:'Low-information features',redundancy:'Redundant features',outliers:'Outlier samples'})){const st=r.statistics[k],tr=document.createElement('tr');for(const x of [name,base.sensitivity['2.5'].cutoffs[k],r.sensitivity['2.5'].cutoffs[k],base.sensitivity['10'].cutoffs[k],r.sensitivity['10'].cutoffs[k],r.n_matrices_with_a_value[k],fmt(st.median)+' ('+fmt(st.q1)+'–'+fmt(st.q3)+')']){const td=document.createElement('td');td.textContent=typeof x==='number'?fmt(x):x;tr.appendChild(td)}q('cutoffs').appendChild(tr)}q('coverage').textContent=p.requires_partial_acknowledgement?'Incomplete coverage: '+p.failed_or_partial_studies.length+' studies have failed checks/transfers; '+p.unknown_date_studies+' public studies have unknown/conflicting release dates; '+p.discovery_errors.length+' discovery requests failed. Review the downloaded records before activation.':'All selected studies processed without reported failed checks or transfers. Unassessable scores are excluded separately for each metric; they are never zero-filled.';q('ack-label').hidden=!p.requires_partial_acknowledgement;q('approve').disabled=s.state==='approved';q('downloads').replaceChildren();for(const name of ['candidate.json','scores.json','cohort.json','status.json']){const a=document.createElement('a');a.href='/api/thresholds/'+current+'/download?file='+name;a.textContent='Download '+name;a.style.marginRight='15px';q('downloads').appendChild(a)}}}
async function poll(){if(!current)return;const id=current;try{const s=await api('/'+id);if(id!==current)return;render(s);if(['discovering','starting','running'].includes(s.state))timer=setTimeout(poll,1800)}catch(e){error(e)}}
q('prepare').onclick=async()=>{try{q('error').hidden=true;q('review').hidden=true;q('ack').checked=false;q('prepare').disabled=true;const d=await api('/prepare',{start_date:q('from').value,end_date:q('through').value,mode:q('mode').value});current=d.id;clearTimeout(timer);await poll();await overview()}catch(e){error(e)}finally{q('prepare').disabled=false}};
q('history').onchange=()=>{current=q('history').value;clearTimeout(timer);q('ack').checked=false;if(current)poll()};
for(const [id,action]of [['start','start'],['pause','pause']])q(id).onclick=async()=>{try{q(id).disabled=true;await api('/'+current+'/'+action,{});clearTimeout(timer);setTimeout(poll,500)}catch(e){error(e)}};
q('approve').onclick=async()=>{try{await api('/'+current+'/approve',{sha256:candidate.sha256,accept_partial:q('ack').checked});try{localStorage.setItem('merit-reference-changed',Date.now()+'')}catch{}await poll();await overview()}catch(e){error(e)}};
q('restore').onclick=async()=>{if(!confirm('Restore the original R1 for analytical alerts? Existing custom score cut-offs are retained.'))return;try{await api('/restore',{});try{localStorage.setItem('merit-reference-changed',Date.now()+'')}catch{}await overview()}catch(e){error(e)}};
for(const id of ['from','through','mode'])q(id).addEventListener('change',()=>{current=null;clearTimeout(timer);q('start').disabled=true;q('review').hidden=true;q('selection').textContent='Selection changed. Click Find public studies to prepare this cohort. Previously started runs remain in the saved-run selector.'});
overview().catch(error);
</script></body></html>'''
